function langSwitch(){return `<div class="lang-switch">${['kk','ru','en'].map(x=>`<button class="lang-btn ${state.lang===x?'active':''}" data-lang="${x}">${x.toUpperCase()}</button>`).join('')}</div>`}
function brand(){return `<div class="brand"><img class="logo" src="assets/atu-logo.webp" alt="ATU"><div class="brand-copy"><strong>EcoFood ATU</strong><small>Smart Food Waste Platform</small></div></div>`}
function landing(){return `<div><nav class="public-nav">${brand()}<div class="public-links"><a href="#about">${L().about}</a><a href="#features">${L().features}</a><a href="#workflow">${L().workflow}</a>${langSwitch()}<button class="btn btn-blue" data-action="login">${L().login}</button></div></nav><main><section class="hero" id="about"><div class="hero-inner"><div><span class="eyebrow">${L().eyebrow}</span><h1>${L().heroTitle}</h1><p class="hero-copy">${L().heroText}</p><div class="hero-actions"><button class="btn btn-primary" data-action="login">${L().start} →</button><a class="btn btn-soft" href="#features">${L().explore}</a></div><div class="trust-row"><div class="trust-item"><strong>2026</strong><span>${L().demoData}</span></div><div class="trust-item"><strong>6</strong><span>${L().modules}</span></div><div class="trust-item"><strong>KK · RU · EN</strong><span>${L().languages}</span></div></div></div><div class="hero-visual"><div class="orbit"></div><div class="leaf-card main"><div class="visual-top"><img class="mini-logo" src="assets/atu-logo.webp" alt="ATU"><span class="status approved">ESG demo</span></div><div class="big-kpi">73%</div><span class="muted">Waste diversion rate</span><div class="spark"><svg viewBox="0 0 320 100" aria-hidden="true"><path d="M0 80 C50 75 65 42 110 55 S170 65 205 32 S270 42 320 10" fill="none" stroke="#15966a" stroke-width="5" stroke-linecap="round"/><path d="M0 80 C50 75 65 42 110 55 S170 65 205 32 S270 42 320 10 L320 100 L0 100Z" fill="#e5f7ef"/></svg></div></div><div class="leaf-card small"><strong>Today · demo</strong><div class="mini-list"><div class="mini-row"><span>Main Canteen</span><b>48 kg</b></div><i style="width:82%"></i><div class="mini-row"><span>Dormitory #1</span><b>22 kg</b></div><i style="width:42%"></i></div></div></div></div></section><section class="section" id="features"><div class="section-inner"><div class="section-head"><span class="eyebrow">EcoFood ATU</span><h2>${L().featureTitle}</h2><p class="section-sub">${L().featureSub}</p></div><div class="feature-grid">${features().map(f=>`<article class="feature-card"><div class="feature-icon">${f.i}</div><h3>${L()[f.k]}</h3><p>${f.d}</p></article>`).join('')}</div></div></section><section class="section flow-section" id="workflow"><div class="section-inner"><div class="section-head"><h2>${L().flowTitle}</h2><p class="section-sub">${L().flowSub}</p></div><div class="flow">${['Collect & identify','Register & document','Review & approve','Analyze & improve'].map((x,i)=>`<div class="flow-step"><b>${i+1}</b><h3>${x}</h3><p>${['QR identifies the location and source.','A structured form records weight and evidence.','Responsible staff verify and update status.','Reports and ESG indicators support decisions.'][i]}</p></div>`).join('')}</div></div></section></main><footer class="landing-footer"><div class="footer-inner">${brand()}<span>© 2026 EcoFood ATU · Demonstration MVP</span></div></footer></div>`}
function login(){return `<div class="login-page"><section class="login-side">${brand()}<div class="login-quote"><h2>${L().heroTitle.replace(/<[^>]*>/g,'')}</h2><p>${L().heroText}</p></div><small>ATU University · Almaty</small></section><section class="login-form-wrap"><form class="login-card" id="loginForm"><button type="button" class="btn btn-soft" data-action="landing">← ${L().about}</button><h1>${L().loginTitle}</h1><p class="muted">${L().loginSub}</p><div class="field"><label>${L().email}</label><input name="email" type="email" placeholder="name@atu.kz" required autocomplete="email"></div><div class="field"><label>${L().password}</label><input name="password" type="password" placeholder="••••••••" minlength="4" required autocomplete="current-password"></div><div class="login-row">${langSwitch()}<a href="#" data-action="forgot">${L().forgot}</a></div><button class="btn btn-primary full" type="submit">${L().login}</button><div class="demo-note">ⓘ ${L().demoNote}</div></form></section></div>`}
function navItems(){return ['dashboard','forms','mobile','submissions','organizations','reports','analytics'].map(p=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}"><span class="nav-icon">${icons[p]}</span>${L()[p]}</button>`).join('')}
function appShell(){return `<div class="app-shell"><aside class="sidebar">${brand()}<nav class="side-nav">${navItems()}</nav><div class="sidebar-bottom"><div class="demo-chip">${L().demoBanner}</div><button class="nav-item ${state.page==='settings'?'active':''}" data-page="settings"><span class="nav-icon">⚙</span>${L().settings}</button><button class="nav-item" data-action="logout"><span class="nav-icon">↩</span>${L().logout}</button></div></aside><main class="app-main"><header class="app-header"><img class="mobile-brand" src="assets/atu-logo.webp" alt="ATU"><h2 class="header-title">${L()[state.page]}</h2><div class="header-actions">${langSwitch()}<button class="icon-btn" data-page="notifications" aria-label="${L().notifications}">♢<span class="badge-dot"></span></button><div class="profile"><div class="avatar">AD</div><div><strong>Aida D.</strong><small>${state.role}</small></div></div></div></header><div class="content">${pageContent()}</div></main><nav class="mobile-nav"><button data-page="dashboard" class="${state.page==='dashboard'?'active':''}"><span>◫</span>${L().dashboard}</button><button data-page="forms" class="${state.page==='forms'?'active':''}"><span>▤</span>${L().forms}</button><button data-page="mobile" class="${state.page==='mobile'?'active':''}"><span>⌁</span>${L().mobile}</button><button data-page="reports" class="${state.page==='reports'?'active':''}"><span>⇩</span>${L().reports}</button><button data-page="settings" class="${state.page==='settings'?'active':''}"><span>⚙</span>${L().settings}</button></nav></div>`}
function intro(title,sub,action=''){return `<div class="page-intro"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function statusText(s){return L()[s]||s}function rows(limit){return state.reports.slice(0,limit).map(r=>`<tr><td><b>${r.id}</b></td><td>${r.org}</td><td>${r.date}</td><td>${r.type}</td><td>${r.kg} kg</td><td><span class="status ${r.status}">${statusText(r.status)}</span></td></tr>`).join('')}
function table(limit=99){return `<table class="data-table"><thead><tr><th>${L().id}</th><th>${L().org}</th><th>${L().date}</th><th>${L().category}</th><th>${L().amount}</th><th>${L().status}</th></tr></thead><tbody>${rows(limit)}</tbody></table>`}
function dashboard(){return `${intro(L().dashboard,L().dashSub,`<button class="btn btn-primary" data-page="forms">＋ ${L().newReport}</button>`)}<div class="stat-grid"><div class="stat-card"><div class="stat-top">${L().totalWaste}<span>◫</span></div><strong>1,284 kg</strong><span class="delta">↓ 12.4% demo</span></div><div class="stat-card"><div class="stat-top">${L().diverted}<span>↗</span></div><strong>73%</strong><span class="delta">↑ 8.2% demo</span></div><div class="stat-card"><div class="stat-top">${L().pending}<span>⌁</span></div><strong>${state.reports.filter(x=>x.status==='review').length}</strong><span class="muted">demo queue</span></div><div class="stat-card"><div class="stat-top">${L().orgs}<span>◎</span></div><strong>8</strong><span class="muted">6 active today</span></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><h3>${L().trend}</h3><div class="legend"><span>2026 demo</span></div></div><div class="chart-wrap"><svg viewBox="0 0 700 240" preserveAspectRatio="none" aria-label="Waste trend demo chart"><g stroke="#e7ecf3"><path d="M0 40H700M0 90H700M0 140H700M0 190H700"/></g><path d="M0 190 C60 155 85 165 140 125 S230 150 285 105 S370 120 430 72 S520 98 570 55 S650 62 700 25" fill="none" stroke="#15966a" stroke-width="5"/><path d="M0 190 C60 155 85 165 140 125 S230 150 285 105 S370 120 430 72 S520 98 570 55 S650 62 700 25 L700 240H0Z" fill="#e6f7ef" opacity=".8"/></svg></div></section><section class="card"><div class="card-head"><h3>${L().composition}</h3></div><div class="donut-layout"><div class="donut"><div class="donut-label"><strong>1.28 t</strong>demo</div></div><div class="donut-legend"><span><i class="dot" style="background:#15966a"></i>Mixed 46%</span><span><i class="dot" style="background:#ffd51c"></i>Bakery 27%</span><span><i class="dot" style="background:#1f5bb0"></i>Vegetables 16%</span><span><i class="dot" style="background:#e2e8f0"></i>Other 11%</span></div></div></section></div><section class="card table-card"><div class="card-head"><h3>${L().recent}</h3><button class="btn btn-soft" data-page="submissions">${L().submissions} →</button></div>${table(4)}</section>`}
function forms(){return `${intro(L().forms,L().formSub)}<form class="card" id="wasteForm"><div class="form-grid"><div class="field"><label>${L().org}</label><select name="org" required><option>Main Canteen</option><option>Dormitory #1</option><option>Training Restaurant</option></select></div><div class="field"><label>${L().source}</label><select name="source" required><option>Preparation zone</option><option>Serving line</option><option>Plate waste station</option></select></div><div class="field"><label>${L().category}</label><select name="type" required><option>Mixed food</option><option>Bakery</option><option>Vegetables</option><option>Dairy</option></select></div><div class="field"><label>${L().weight}</label><input name="kg" type="number" min="0.1" step="0.1" placeholder="0.0" required></div><div class="field span-2"><label>${L().notes}</label><textarea name="notes" placeholder="Optional demo note"></textarea></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="draft">${L().saveDraft}</button><button class="btn btn-green" type="submit">${L().submit}</button></div></form>`}
function mobileInput(){return `${intro(L().mobile,L().mobileSub)}<div class="mobile-capture"><section class="card"><h3>${L().scan}</h3><p class="muted">${L().scanHint}</p><div class="scan-zone"><div><div class="scan-icon">▦</div><b id="scanResult">ATU collection point QR</b></div></div><button class="btn btn-blue full" data-action="scan" style="margin-top:14px">⌁ ${L().scan}</button></section><section class="phone-frame"><div class="phone-top"><strong>EcoFood Mobile</strong><div style="font-size:12px;opacity:.8;margin-top:4px">Quick capture · demo</div></div><div class="phone-body"><div class="field"><label>${L().source}</label><input id="mobileSource" value="Not scanned" readonly></div><div class="field"><label>${L().weight}</label><input type="number" placeholder="0.0"></div><label class="btn btn-soft full">▧ ${L().photo}<input id="photoInput" type="file" accept="image/*" capture="environment" hidden></label><img id="photoPreview" class="photo-preview" alt="Uploaded waste evidence preview"><button class="btn btn-green full" style="margin-top:14px" data-action="mobileSave">${L().submit}</button></div></section></div>`}
function submissions(){let selected=state.reports.find(x=>x.status==='review')||state.reports[0];return `${intro(L().submissions,L().workflowSub)}<div class="review-panel"><section class="card table-card"><div class="card-head"><h3>${L().recent}</h3><span class="status review">${L().review}</span></div>${table()}</section><aside class="card"><div class="card-head"><h3>${selected.id}</h3><span class="status ${selected.status}">${statusText(selected.status)}</span></div><div class="timeline"><div class="timeline-item"><span class="timeline-dot"></span><div><strong>Created</strong><p>${selected.org} · ${selected.date}</p></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><strong>${L().submit}</strong><p>${selected.kg} kg · ${selected.type}</p></div></div><div class="timeline-item"><span class="timeline-dot" style="background:#fff4cc;border-color:#ffe383"></span><div><strong>${L().review}</strong><p>Aida D. · reviewer</p></div></div></div><div class="field"><label>${L().comment}</label><textarea id="reviewComment"></textarea></div><div class="form-actions"><button class="btn btn-danger" data-action="return" data-id="${selected.id}">${L().sendBack}</button><button class="btn btn-green" data-action="approve" data-id="${selected.id}">${L().accept}</button></div></aside></div>`}
function organizations(){let orgs=[['MC','Main Canteen','User · Reviewer · Administrator'],['BC','Building B Canteen','User · Reviewer'],['CC','Building C Canteen','User · Reviewer'],['CP','Coffee Point','User · Reviewer'],['INN','ATU INN','User · Reviewer'],['FTD','Food Technology Department','User · Reviewer']];return `${intro(L().organizations,L().orgSub)}<div class="org-grid">${orgs.map(o=>`<article class="org-card"><div class="org-mark">${o[0]}</div><h3>${o[1]}</h3><p>${o[2]}</p></article>`).join('')}</div>`}
function reports(){return `${intro(L().reports,L().reportSub)}<div class="report-actions"><article class="action-card"><div class="feature-icon">X</div><h3>${L().excel}</h3><p>Downloads the currently visible demo registry in an Excel-compatible .xls file.</p><button class="btn btn-green" data-action="excel">⇩ ${L().download}</button></article><article class="action-card"><div class="feature-icon">PDF</div><h3>${L().pdf}</h3><p>Opens a print-ready view; choose “Save as PDF” in your browser.</p><button class="btn btn-blue" data-action="pdf">⇩ ${L().download}</button></article><article class="action-card"><div class="feature-icon">◫</div><h3>Registry</h3><p>${state.reports.length} demo records · ${state.reports.reduce((a,b)=>a+b.kg,0)} kg total.</p><button class="btn btn-soft" data-page="submissions">${L().submissions} →</button></article></div><section class="card table-card"><div class="card-head"><h3>${L().recent}</h3><div class="table-tools"><input id="reportSearch" placeholder="Search"><select id="statusFilter"><option value="">All status</option><option value="approved">${L().approved}</option><option value="review">${L().review}</option><option value="returned">${L().returned}</option></select></div></div><div id="reportTable">${table()}</div></section>`}
function analytics(){return `${intro(L().analytics,L().analyticsSub)}<div class="esg-grid"><div class="esg-card green"><small>${L().co2} · demo estimate</small><strong>2.8 t</strong><span>CO₂e</span></div><div class="esg-card blue"><small>${L().water} · demo estimate</small><strong>184 m³</strong><span>water</span></div><div class="esg-card gold"><small>${L().cost} · demo estimate</small><strong>₸ 412k</strong><span>potential</span></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><h3>Waste intensity by unit</h3><span class="status draft">demo</span></div><div class="chart-wrap"><svg viewBox="0 0 700 240"><g fill="#dfe8f5"><rect x="35" y="30" width="70" height="180" rx="7"/><rect x="150" y="80" width="70" height="130" rx="7"/><rect x="265" y="55" width="70" height="155" rx="7"/><rect x="380" y="112" width="70" height="98" rx="7"/><rect x="495" y="94" width="70" height="116" rx="7"/><rect x="610" y="135" width="55" height="75" rx="7"/></g><g fill="#15966a"><rect x="35" y="88" width="70" height="122" rx="7"/><rect x="150" y="120" width="70" height="90" rx="7"/><rect x="265" y="102" width="70" height="108" rx="7"/><rect x="380" y="145" width="70" height="65" rx="7"/><rect x="495" y="132" width="70" height="78" rx="7"/><rect x="610" y="160" width="55" height="50" rx="7"/></g></svg></div></section><section class="card"><div class="card-head"><h3>ESG KPI notes</h3></div><p class="muted" style="line-height:1.7">All values in this MVP are illustrative demo estimates, clearly separated from verified university performance. Production calculations require approved emission factors, measured baselines and auditable source data.</p><div class="demo-note">Formula preview: diverted waste × category emission factor. No claim of audited impact is made.</div></section></div>`}
function notifications(){let ns=[['⇄','EF-2041','Main Canteen report awaits review','2 min'],['✓','EF-2040','Building B Canteen report approved','1 h'],['!','EF-2039','Building C Canteen report returned','3 h']];return `${intro(L().notifications,L().notifSub)}<div class="notification-list">${ns.map((n,i)=>`<article class="notification ${i<2?'unread':''}"><div class="feature-icon">${n[0]}</div><div><h4>${n[1]}</h4><p>${n[2]}</p></div><time>${n[3]}</time></article>`).join('')}</div>`}
function settings(){return `${intro(L().settings,L().settingsSub)}<div class="settings-grid"><section class="card"><div class="card-head"><h3>${L().profileSettings}</h3></div><div class="field"><label>${L().email}</label><input value="Demo user" readonly></div><div class="field"><label>Role</label><select id="roleSelect"><option ${state.role==='Reviewer'?'selected':''}>Reviewer</option><option ${state.role==='Operator'?'selected':''}>Operator</option><option ${state.role==='Administrator'?'selected':''}>Administrator</option></select></div><div class="field"><label>${L().languages}</label>${langSwitch()}</div></section><section class="card"><div class="card-head"><h3>${L().notificationSettings}</h3></div>${[['email','emailNotif'],['push','pushNotif'],['weekly','weekly']].map(x=>`<div class="setting-row"><span>${L()[x[1]]}</span><button class="switch ${state.settings[x[0]]?'on':''}" data-setting="${x[0]}" aria-label="Toggle ${L()[x[1]]}"></button></div>`).join('')}</section></div>`}
function pageContent(){return ({dashboard,forms,mobile:mobileInput,submissions,organizations,reports,analytics,notifications,settings}[state.page]||dashboard)()}
function render(){document.documentElement.lang=state.lang;document.getElementById('app').innerHTML=state.view==='landing'?landing():state.view==='login'?login():appShell();bind()}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function addReport(status){let form=document.getElementById('wasteForm'),data=new FormData(form);let kg=Number(data.get('kg')||0);if(status!=='draft'&&!form.reportValidity())return;state.reports.unshift({id:`EF-${2042+state.reports.length}`,org:data.get('org')||'Main Canteen',date:'06.11.2026',type:data.get('type')||'Mixed food',kg:kg||0,status});toast(status==='draft'?L().saveDraft:L().submit);state.page='submissions';render()}
function exportExcel(){let html=`<html><meta charset="utf-8"><table><tr>${['ID','Organization','Date','Category','Weight kg','Status'].map(x=>`<th>${x}</th>`).join('')}</tr>${state.reports.map(r=>`<tr><td>${r.id}</td><td>${r.org}</td><td>${r.date}</td><td>${r.type}</td><td>${r.kg}</td><td>${r.status}</td></tr>`).join('')}</table></html>`;let blob=new Blob([html],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ecofood-atu-demo-report.xls';a.click();URL.revokeObjectURL(a.href);toast(L().excel)}
function filterReports(){let q=(document.getElementById('reportSearch')?.value||'').toLowerCase(),s=document.getElementById('statusFilter')?.value||'';let original=state.reports;let filtered=original.filter(r=>(!s||r.status===s)&&JSON.stringify(r).toLowerCase().includes(q));document.querySelector('#reportTable tbody').innerHTML=filtered.map(r=>`<tr><td><b>${r.id}</b></td><td>${r.org}</td><td>${r.date}</td><td>${r.type}</td><td>${r.kg} kg</td><td><span class="status ${r.status}">${statusText(r.status)}</span></td></tr>`).join('')||`<tr><td colspan="6" class="empty">No matching records</td></tr>`}
function bind(){
  document.querySelectorAll('[data-lang]').forEach(button=>button.onclick=()=>{state.lang=button.dataset.lang;localStorage.setItem('ecofood-language',state.lang);render()});
  document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{state.view='app';state.page=button.dataset.page;render();scrollTo(0,0)});
  document.querySelectorAll('[data-action]').forEach(button=>button.onclick=event=>{
    const action=button.dataset.action;
    if(action==='login'){state.view='login';render()}
    if(action==='landing'||action==='logout'){state.view='landing';render()}
    if(action==='forgot'){event.preventDefault();toast('Demo mode: password recovery is not connected.')}
    if(action==='draft')addReport('draft');
    if(action==='scan'){
      document.getElementById('scanResult').textContent='✓ Main Canteen · Point MC-03';
      document.getElementById('mobileSource').value='Main Canteen · MC-03';
      toast('Demo QR resolved: MC-03');
    }
    if(action==='mobileSave')toast('Mobile demo entry validated — use Digital Forms to submit.');
    if(action==='approve'||action==='return'){
      const report=state.reports.find(item=>item.id===button.dataset.id);
      if(report){report.status=action==='approve'?'approved':'returned';toast(statusText(report.status));render()}
    }
    if(action==='excel')exportExcel();
    if(action==='pdf')window.print();
    if(action==='readAll'){
      document.querySelectorAll('.notification.unread').forEach(item=>item.classList.remove('unread'));
      toast('Notifications marked as read');
    }
    if(action==='demoOnly')toast(L().demoBanner);
  });
  const loginForm=document.getElementById('loginForm');
  if(loginForm)loginForm.onsubmit=event=>{event.preventDefault();if(loginForm.reportValidity()){state.view='app';state.page='dashboard';render()}};
  const wasteForm=document.getElementById('wasteForm');
  if(wasteForm)wasteForm.onsubmit=event=>{event.preventDefault();addReport('review')};
  const photoInput=document.getElementById('photoInput');
  if(photoInput)photoInput.onchange=()=>{
    const file=photoInput.files[0];
    if(file){const preview=document.getElementById('photoPreview');preview.src=URL.createObjectURL(file);preview.style.display='block';toast('Photo preview loaded locally')}
  };
  document.querySelectorAll('[data-setting]').forEach(button=>button.onclick=()=>{
    const key=button.dataset.setting;state.settings[key]=!state.settings[key];button.classList.toggle('on',state.settings[key]);toast(L().settings)
  });
  const roleSelect=document.getElementById('roleSelect');
  if(roleSelect)roleSelect.onchange=()=>{state.role=roleSelect.value;toast(`Role: ${state.role}`)};
  const search=document.getElementById('reportSearch');
  const filter=document.getElementById('statusFilter');
  if(search)search.oninput=filterReports;
  if(filter)filter.onchange=filterReports;
}
